// crt0's thread root (the entry SetupThread is given in _start): calls the ExitThread syscall (0x23).
__asm__(
    ".set noreorder\n"
    ".set noat\n"
    ".text\n"
    ".globl _root\n"
    ".ent _root\n"
    "_root:\n"
    "addiu $3, $0, 0x23\n"
    "syscall 0\n"
    ".end _root\n"
    ".set at\n"
    ".set reorder\n"
);

